import os
from functools import lru_cache
from pathlib import Path
from dotenv import load_dotenv
from pydantic import BaseModel, Field

# Locate and load the backend .env file
BACKEND_DIR = Path(__file__).resolve().parent.parent
ENV_PATH = BACKEND_DIR / ".env"
load_dotenv(dotenv_path=ENV_PATH)


class Settings(BaseModel):
    litellm_api_key: str = Field(
        default_factory=lambda: os.getenv("LITELLM_API_KEY", "")
    )
    litellm_base_url: str = Field(
        default_factory=lambda: os.getenv(
            "LITELLM_BASE_URL", "https://litellm.vision.aivar.app/v1"
        )
    )
    litellm_model: str = Field(
        default_factory=lambda: os.getenv("LITELLM_MODEL", "")
    )
    neatlogs_api_key: str = Field(
        default_factory=lambda: os.getenv("NEATLOGS_API_KEY", "")
    )
    host: str = Field(default_factory=lambda: os.getenv("HOST", "0.0.0.0"))
    port: int = Field(default_factory=lambda: int(os.getenv("PORT", "8000")))
    cors_origins: list[str] = ["*"]


@lru_cache()
def get_settings() -> Settings:
    return Settings()

